class LocalStorageAdapter {
  async get(key) {
    try {
      return globalThis.localStorage.getItem(key);
    } catch {
      return null;
    }
  }
  async set(key, value) {
    try {
      globalThis.localStorage.setItem(key, value);
    } catch {
      // Storage full or unavailable
    }
  }
  async remove(key) {
    try {
      globalThis.localStorage.removeItem(key);
    } catch {
      // Ignore
    }
  }
}

export { LocalStorageAdapter };
